    function isSurchargePoolKind() {
      return currentPoolKind === 'surcharge';
    }

    /** 加收服务费池规则页：将小费相关文案替换为加收服务费 */
    function tipTerm(text) {
      if (!isSurchargePoolKind() || text == null) return text;
      return String(text)
        .replace(/小费池/g, '加收服务费池')
        .replace(/小费/g, '加收服务费');
    }

    function getCondTypeNames(extra) {
      var names = Object.assign({
        role: '角色', employee: '员工', area: '订单区域', orderType: '订单类型',
        hours: '订单时间段', tipType: '小费类型', containsProduct: '订单需包含商品',
        shift: '班次', weekday: '周期（星期）'
      }, extra || {});
      if (!isSurchargePoolKind()) return names;
      var out = {};
      Object.keys(names).forEach(function(k) { out[k] = tipTerm(names[k]); });
      return out;
    }

