        row('组：', ids.group, '请先选择产品线', menuCascadePlaceholderHtml('请先选择产品线'), 'group') +
        row('类：', ids.category, '请先选择组', menuCascadePlaceholderHtml('请先选择组'), 'category') +
        row('菜：', ids.item, '请先选择类', menuCascadePlaceholderHtml('请先选择类'), 'item');
