          '<a href="javascript:void(0)" class="btn-link" style="color:var(--danger);font-size:13px;margin-left:8px" onclick="removeReceiverPrimaryRow(this)">删除</a>' +
        '</td>';
      const secondaryRow = document.createElement('tr');
